-- SmartGift pricelist export (postgres)
-- generated: 2026-08-29T15:23:01.508Z

CREATE TABLE IF NOT EXISTS catalogs (
  catalog_key   TEXT PRIMARY KEY,
  label         TEXT NOT NULL,
  product_count INTEGER NOT NULL DEFAULT 0,
  source_url    TEXT NOT NULL,
  synced_at     TIMESTAMPTZ NOT NULL DEFAULT NOW()
);

CREATE TABLE IF NOT EXISTS products (
  id             BIGSERIAL PRIMARY KEY,
  catalog_key    TEXT NOT NULL REFERENCES catalogs(catalog_key) ON DELETE CASCADE,
  code           TEXT NOT NULL,
  name           TEXT,
  rmb            NUMERIC(12,4),
  upc            INTEGER,
  dim_l          NUMERIC(10,2),
  dim_w          NUMERIC(10,2),
  dim_h          NUMERIC(10,2),
  kg             NUMERIC(10,3),
  exclusive_flag BOOLEAN NOT NULL DEFAULT FALSE,
  img            TEXT,
  synced_at      TIMESTAMPTZ NOT NULL DEFAULT NOW(),
  UNIQUE (catalog_key, code)
);

TRUNCATE products RESTART IDENTITY CASCADE;
TRUNCATE catalogs CASCADE;

